       radio, zunchado, origen, notas)
  JOIN species s ON s.scientific_name = v.especie
  JOIN catalog_items t ON t.code = v.tipo
  JOIN catalog_types tt ON tt.id = t.catalog_type_id AND tt.code = 'GREEN_ELEMENT_TYPE';

